const tiers=[{id:'high',name:'High',caption:'Leading the way',symbol:'↟',tint:'#f8e8a0',ink:'#76601c'},{id:'mid',name:'Mid',caption:'Holding it down',symbol:'≈',tint:'#dcd9f7',ink:'#575198'},{id:'newer',name:'Newer',caption:'Finding their feet',symbol:'✧',tint:'#cde6fa',ink:'#326b95'},{id:'unsorted',name:'Unsorted',caption:'A place to start',symbol:'☷',tint:'#f1f3eb',ink:'#7c8671'}];
const key='roster-tier-list-v1';let names=[];let editing=null;let storageAvailable=true;
try{const data=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(data))names=data.filter(n=>typeof n.id==='string'&&typeof n.name==='string'&&tiers.some(t=>t.id===n.tier));}catch{storageAvailable=false;}
const board=document.querySelector('#board');const status=document.querySelector('#status');const dialog=document.querySelector('#edit-dialog');
// The skill board follows the active lobby; the standalone roster stays local.
let sharedRoster = null;
function boardNames(){return sharedRoster ? sharedRoster.players : names;}
function setSharedRoster(roster){
  const connectionChanged = !!sharedRoster !== !!roster || sharedRoster?.connected !== roster?.connected;
  sharedRoster = roster;
  document.querySelector('#add-form').closest('section').hidden = !!roster;
  document.querySelector('#delete').hidden = !!roster;
  if(dialog.open && (!boardNames().some(p=>p.id===editing) || (roster && !roster.canEdit(editing)))) dialog.close();
  if(connectionChanged) status.textContent = roster ? (roster.connected ? 'Lobby roster · Skill levels sync for everyone. Edit your own level; the host can edit anyone.' : 'Offline · Showing the last synced skill levels.') : '';
  render();
}
window.addEventListener('roster:sync', event => setSharedRoster(event.detail));
function movePerson(person,tier){
  if(sharedRoster){
    if(sharedRoster.canEdit(person.id)) sharedRoster.update(person.id,{tier});
    return;
  }
  person.tier=tier;save(`${person.name} moved to ${tiers.find(t=>t.id===tier).name}.`);
}
function save(message){try{localStorage.setItem(key,JSON.stringify(names));storageAvailable=true;}catch{storageAvailable=false;}status.textContent=storageAvailable?message:'Browser storage is unavailable. Changes will last until you close this page.';document.querySelector('.local').lastChild.textContent=storageAvailable?' Saved on this device':' Not saved on this device';render();}
function render(){board.replaceChildren();document.querySelector('#total').textContent=boardNames().length;for(const tier of tiers){const members=boardNames().filter(n=>n.tier===tier.id);const section=document.createElement('section');section.className='tier-row '+tier.id;section.style.setProperty('--tint',tier.tint);section.style.setProperty('--ink',tier.ink);section.setAttribute('aria-label',tier.name+' tier');section.innerHTML=`<div class="tier-label"><span class="count">${members.length}</span><div class="tier-name"><span class="symbol" aria-hidden="true">${tier.symbol}</span>${tier.name}</div><span class="tier-caption">${tier.caption}</span></div><div class="tier-body"></div>`;const body=section.querySelector('.tier-body');if(!members.length){const empty=document.createElement('span');empty.className='empty';empty.textContent=tier.id==='unsorted'?'Not sure yet? Start here.':'A little quiet here. Add your first name.';body.append(empty);}for(const person of members){const chip=document.createElement('button');chip.className='name-chip';chip.disabled=!!sharedRoster&&!sharedRoster.canEdit(person.id);chip.draggable=!chip.disabled;chip.setAttribute('aria-label',`Edit or move ${person.name}`);const label=document.createElement('span');label.className='name';label.textContent=person.name;const dots=document.createElement('span');dots.className='chip-dots';dots.textContent='⋮';chip.append(label,dots);chip.onclick=()=>openEdit(person);chip.ondragstart=e=>{e.dataTransfer.setData('text/plain',person.id);e.dataTransfer.effectAllowed='move';};chip.ondragend=()=>document.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'));body.append(chip);}const add=document.createElement('button');add.className='add-inline';add.textContent='＋ Add name';add.setAttribute('aria-label','Add name to '+tier.name);add.onclick=()=>{document.querySelector('#tier').value=tier.id;document.querySelector('#name').focus();};if(!sharedRoster)body.append(add);section.ondragover=e=>{e.preventDefault();section.classList.add('drag-over');};section.ondragleave=e=>{if(!section.contains(e.relatedTarget))section.classList.remove('drag-over');};section.ondrop=e=>{e.preventDefault();section.classList.remove('drag-over');const person=boardNames().find(n=>n.id===e.dataTransfer.getData('text/plain'));if(person)movePerson(person,tier.id);};board.append(section);}}
document.querySelector('#add-form').onsubmit=e=>{e.preventDefault();if(sharedRoster)return;const input=document.querySelector('#name');const name=input.value.trim();if(!name){input.setCustomValidity('Enter a name to add.');input.reportValidity();return;}names.push({id:crypto.randomUUID(),name,tier:document.querySelector('#tier').value});input.value='';save(`${name} added to the board.`);input.focus();};document.querySelector('#name').oninput=e=>e.target.setCustomValidity('');
function openEdit(person){if(sharedRoster&&!sharedRoster.canEdit(person.id))return;editing=person.id;document.querySelector('#edit-name').value=person.name;document.querySelector('#edit-tier').value=person.tier;dialog.showModal();}
document.querySelector('#close').onclick=()=>dialog.close();document.querySelector('#edit-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#edit-name').value.trim();if(!name){document.querySelector('#edit-name').focus();return;}const person=boardNames().find(n=>n.id===editing);if(person){const tier=document.querySelector('#edit-tier').value;if(sharedRoster){if(sharedRoster.canEdit(person.id))sharedRoster.update(person.id,{name,tier});}else{person.name=name;person.tier=tier;save('Name updated.');}}dialog.close();};document.querySelector('#delete').onclick=()=>{if(sharedRoster)return;names=names.filter(n=>n.id!==editing);save('Name removed.');dialog.close();};render();if(!storageAvailable){document.querySelector('.local').lastChild.textContent=' Storage unavailable';status.textContent='Browser storage is unavailable. Changes may not persist.';}
